<?php

declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('ADMIN');
if (is_post()) {
    verify_csrf_or_abort();
    $result = ((string)($_POST['action'] ?? '') === 'toggle_supplier') ? admin_toggle_supplier((int)($_POST['supplier_id'] ?? 0)) : ['ok' => false, 'message' => 'Choose a valid supplier action.'];
    flash($result['ok'] ? 'success' : 'error', $result['message']);
    redirect('admin/suppliers.php');
}
$q = trim((string)($_GET['q'] ?? ''));
$status = strtoupper(trim((string)($_GET['status'] ?? 'ALL')));
if (!in_array($status, ['ALL', 'ACTIVE', 'INACTIVE'], true)) $status = 'ALL';
$suppliers = admin_suppliers(compact('q', 'status'));
$counts = admin_supplier_counts();
$pageTitle = 'Suppliers'; $bodyClass = 'portal-page'; require __DIR__ . '/../includes/header.php'; $success = flash('success'); $error = flash('error');
?>
<div class="portal-shell"><?php require __DIR__ . '/../includes/sidebar.php'; ?><main class="portal-main inventory-main"><header class="portal-page-header"><div><span class="eyebrow">INVENTORY</span><h1 class="mt-2 mb-1">Suppliers</h1><p class="text-muted mb-0">Maintain the vendors that provide Franscoffee ingredients, packaging, and shop supplies.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-coffee" href="<?= url('admin/inventory.php') ?>"><i class="bi bi-box-seam me-2"></i>Inventory</a><a class="btn btn-coffee" href="<?= url('admin/supplier-form.php') ?>"><i class="bi bi-plus-lg me-2"></i>Add supplier</a></div></header>
<?php if ($success): ?><div class="alert alert-success"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<section class="supplier-metrics"><div><span>Total suppliers</span><strong><?= $counts['total'] ?></strong></div><div><span>Active</span><strong><?= $counts['active'] ?></strong></div><div><span>Inactive</span><strong><?= $counts['inactive'] ?></strong></div></section>
<section class="portal-card inventory-filter-card"><form method="get" class="supplier-filter-grid"><div><label class="form-label" for="supplierSearch">Search</label><input class="form-control" id="supplierSearch" name="q" value="<?= e($q) ?>" placeholder="Supplier, contact, email, product"></div><div><label class="form-label" for="supplierStatus">Status</label><select class="form-select" id="supplierStatus" name="status"><option value="ALL">All</option><option value="ACTIVE" <?= $status === 'ACTIVE' ? 'selected' : '' ?>>Active</option><option value="INACTIVE" <?= $status === 'INACTIVE' ? 'selected' : '' ?>>Inactive</option></select></div><div class="inventory-filter-actions"><button class="btn btn-coffee">Apply</button><a class="btn btn-outline-secondary" href="<?= url('admin/suppliers.php') ?>">Reset</a></div></form></section>
<section class="portal-card mt-4"><div class="panel-heading"><div><span class="eyebrow">VENDOR DIRECTORY</span><h2><?= count($suppliers) ?> supplier<?= count($suppliers) === 1 ? '' : 's' ?></h2></div></div><?php if (!$suppliers): ?><div class="empty-state compact"><i class="bi bi-truck"></i><h3>No suppliers found</h3><p>Add a supplier to connect stock items to their source.</p></div><?php else: ?><div class="supplier-grid"><?php foreach ($suppliers as $supplier): ?><article class="supplier-card <?= $supplier['status'] !== 'ACTIVE' ? 'is-inactive' : '' ?>"><div class="supplier-card-head"><span class="supplier-icon"><i class="bi bi-truck"></i></span><span class="badge <?= $supplier['status'] === 'ACTIVE' ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= e((string)$supplier['status']) ?></span></div><h3><?= e((string)$supplier['name']) ?></h3><p><?= e((string)($supplier['products_supplied'] ?: 'No supplied products listed yet.')) ?></p><dl><div><dt>Contact</dt><dd><?= e((string)($supplier['contact_person'] ?: '—')) ?></dd></div><div><dt>Phone</dt><dd><?= e((string)($supplier['phone'] ?: '—')) ?></dd></div><div><dt>Email</dt><dd><?= e((string)($supplier['email'] ?: '—')) ?></dd></div><div><dt>Items</dt><dd><?= (int)$supplier['inventory_count'] ?></dd></div></dl><div class="supplier-actions"><a class="btn btn-sm btn-outline-coffee" href="<?= url('admin/supplier-form.php?id=' . (int)$supplier['id']) ?>">Edit</a><a class="btn btn-sm btn-outline-secondary" href="<?= url('admin/inventory.php?supplier_id=' . (int)$supplier['id']) ?>">View stock</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle_supplier"><input type="hidden" name="supplier_id" value="<?= (int)$supplier['id'] ?>"><button class="btn btn-sm <?= $supplier['status'] === 'ACTIVE' ? 'btn-outline-danger' : 'btn-outline-success' ?>" type="submit" data-confirm="<?= $supplier['status'] === 'ACTIVE' ? 'Deactivate this supplier? Existing inventory links remain intact.' : 'Activate this supplier?' ?>"><?= $supplier['status'] === 'ACTIVE' ? 'Deactivate' : 'Activate' ?></button></form></div></article><?php endforeach; ?></div><?php endif; ?></section>
